/*
 * A041558  Numerators of continued fraction convergents to sqrt(297).
 * https://oeis.org/A041558
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the nth convergent to sqrt(297). The
 *            continued fraction of sqrt(297) has the periodic part
 *            [4,3,1,1,2,1,1,3,4,34] after the initial term 17. The numerators
 *            are generated by the recurrence: p_{-2} = 0, p_{-1} = 1, p_n =
 *            a_n * p_{n-1} + p_{n-2}
 * Range:     u8 n <= 2, u16 n <= 9, u32 n <= 18, u64 n <= 38, u128 n <= 77,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Periodic part of the continued fraction for sqrt(297). */
    static const seq_t period[10] = {4, 3, 1, 1, 2, 1, 1, 3, 4, 34};
    const seq_t a0 = 17;            /* floor(sqrt(297)) */

    seq_t p_prev2 = 0;
    seq_t p_prev1 = 1;
    seq_t p_curr  = 0;

    for (idx_t i = 0; i <= n; ++i) {
        seq_t ai = (i == 0) ? a0 : period[(i - 1) % 10];
        p_curr = ai * p_prev1 + p_prev2;
        p_prev2 = p_prev1;
        p_prev1 = p_curr;
    }
    return p_curr;
}
